#!/usr/bin/env python3
# Standalone repro for ducklings==0.1.0 (stdlib only, no harness required).
# To reproduce against the installed library: pip install ducklings==0.1.0
import traceback

def brood(count):
    if count < 0:
        raise ValueError("duckling count must be non-negative")
    return ["duckling-%d" % i for i in range(count)]

def hatch():
    try:
        return brood(-1)
    except ValueError:
        traceback.print_exc()
        raise

if __name__ == "__main__":
    hatch()
